  <script>
    // Normalise typed Eastern Arabic and Persian numerals to Western digits
    function toWesternDigits(str) {
      if (!str) return '';
      const eastern = ['٠','١','٢','٣','٤','٥','٦','٧','٨','٩'];
      const persian = ['۰','۱','۲','۳','۴','۵','۶','۷','۸','۹'];
      return str
        .replace(/[٠-٩]/g, d => eastern.indexOf(d))
        .replace(/[۰-۹]/g, d => persian.indexOf(d));
    }

    const phoneInput = document.getElementById('phone');
    const makaniInput = document.getElementById('makani');
    const form = document.getElementById('addressForm');
    const toast = document.getElementById('saveToast');

    // Live normalisation for phone and Makani inputs
    phoneInput.addEventListener('input', (e) => {
      const cursor = e.target.selectionStart;
      e.target.value = toWesternDigits(e.target.value);
      e.target.setSelectionRange(cursor, cursor);
    });

    makaniInput.addEventListener('input', (e) => {
      let val = toWesternDigits(e.target.value).replace(/\D/g, '').slice(0, 10);
      if (val.length > 5) {
        val = val.slice(0, 5) + ' ' + val.slice(5);
      }
      e.target.value = val;
    });

    // Form submission handling
    form.addEventListener('submit', (e) => {
